import {trimDefaults,roofTrimLayout} from './roof-trim.mjs';
export function setupRoofTrimControls({getState,currentEdge,applyOverhang,checkpoint,render,showDialog}){
 const $=id=>document.getElementById(id),button=document.createElement('button');button.id='addRoofOverhang';button.className='full';button.textContent='Add eave / rake overhang';$('edgeEditor').append(button);
 button.onclick=()=>{const edge=currentEdge();if(!edge)return;showDialog('Add roof overhang','<p class="source">Adds horizontal distance to the selected exterior Eave or Rake, preserving the pitched roof surface and wall positions. Connected collinear rake edges extend together.</p><label>Additional overhang (inches)<input id="overhangInches" type="number" min="0.125" max="48" step="0.125" value="12"></label><button id="applyRoofOverhang" class="primary full">Extend selected roof edge</button><p id="overhangFeedback" role="status"></p>');$('applyRoofOverhang').onclick=()=>{try{applyOverhang(edge,+$('overhangInches').value);$('dialog').close()}catch(error){$('overhangFeedback').textContent=error.message}}};
 const section=document.createElement('section');section.className='report-controls';section.innerHTML='<h2>Eave & fascia trim</h2><button id="roofTrimSetup" class="full">Trim parts & quantities</button>';$('panelSettings').after(section);
 $('roofTrimSetup').onclick=()=>{const s={...trimDefaults,...getState().trim};showDialog('Eave & fascia trim','<label class="check"><input id="enableEaveTrim" type="checkbox" '+(s.eave?'checked':'')+'>Eave trim on labeled Eave edges</label><label class="check"><input id="enableFasciaTrim" type="checkbox" '+(s.fascia?'checked':'')+'>Fascia on labeled Eave and Rake edges</label><div class="form-grid"><label>Fascia face height (in)<input id="fasciaDepth" type="number" min="1" max="24" step="0.125" value="'+s.fasciaDepth+'"></label><label>Eave trim face height (in)<input id="eaveDepth" type="number" min="0.5" max="12" step="0.125" value="'+s.eaveDepth+'"></label><label>Stock piece length (ft)<input id="trimStockLength" type="number" min="1" max="40" step="0.25" value="'+s.stockLength+'"></label><label>Trim color<input id="trimColor" type="color" value="'+s.color+'"></label></div><button id="applyRoofTrim" class="primary full">Apply trim parts</button><p class="source">Lengths follow sloped roof edges. Pieces round up per edge, with no lap allowance or offcut reuse. 3D displays trim faces; manufacturer bends and fasteners are not modeled. These quantities are separate from existing quote pricing.</p><p id="trimTotals" role="status"></p>');const totals=()=>{const t=roofTrimLayout(getState());$('trimTotals').textContent='Eave trim: '+t.eave.toFixed(2)+' linear ft · '+t.eavePieces+' pieces. Fascia: '+t.fascia.toFixed(2)+' linear ft · '+t.fasciaPieces+' pieces.'};$('applyRoofTrim').onclick=()=>{const fasciaDepth=+$('fasciaDepth').value,eaveDepth=+$('eaveDepth').value,stockLength=+$('trimStockLength').value;if(![fasciaDepth,eaveDepth,stockLength].every(Number.isFinite)||fasciaDepth<1||fasciaDepth>24||eaveDepth<.5||eaveDepth>12||stockLength<1||stockLength>40){$('trimTotals').textContent='Check trim heights and stock length limits.';return}checkpoint();getState().trim={eave:$('enableEaveTrim').checked,fascia:$('enableFasciaTrim').checked,fasciaDepth,eaveDepth,stockLength,color:$('trimColor').value};render();totals()};totals()};
}
